t.script:
// 1. Live Saudi Clock
function updateClock() {
    const now = new Date();
    const options = { timeZone: 'Asia/Riyadh', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true };
    const clockEl = document.getElementById('ess_live_clock');
    if (clockEl) {
        clockEl.innerText = now.toLocaleTimeString('ar-SA', options);
    }
}
setInterval(updateClock, 1000);
updateClock();

// 2. Service Worker Registration
if ('serviceWorker' in navigator) {
    navigator.serviceWorker.register('/jandalah/sw.js').then(function() {
        console.log('Jandalah PWA ServiceWorker Registered');
    }).catch(function(err) {
        console.log('SW registration error:', err);
    });
}

// 3. Smart Adaptive PWA Detection
let deferredPrompt = null;
const ua = navigator.userAgent || navigator.vendor || window.opera;
const isIOS = /iPad|iPhone|iPod/.test(ua) && !window.MSStream;
const isCriOS = isIOS && /CriOS/.test(ua);
const isSafari = isIOS && /Safari/.test(ua) && !isCriOS;
const isInApp = /FBAN|FBAV|Instagram|WhatsApp|Twitter|Snapchat/i.test(ua);
const isStandalone = window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone === true;

document.addEventListener('DOMContentLoaded', function() {
    if (isStandalone) {
        return; // Already installed as PWA!
    }

    const pwaContainer = document.getElementById('pwa_smart_container');
    if (!pwaContainer) return;

    if (sessionStorage.getItem('jandalah_pwa_dismissed') === '1') {
        return;
    }

    if (isInApp) {
        pwaContainer.classList.remove('d-none');
        document.getElementById('pwa_inapp_box')?.classList.remove('d-none');
    } else if (isIOS) {
        pwaContainer.classList.remove('d-none');
        if (isSafari) {
            document.getElementById('pwa_ios_safari_box')?.classList.remove('d-none');
        } else {
            document.getElementById('pwa_ios_chrome_box')?.classList.remove('d-none');
        }
    }
});

window.addEventListener('beforeinstallprompt', (e) => {
    e.preventDefault();
    deferredPrompt = e;
    const pwaContainer = document.getElementById('pwa_smart_container');
    if (pwaContainer && sessionStorage.getItem('jandalah_pwa_dismissed') !== '1') {
        pwaContainer.classList.remove('d-none');
        document.getElementById('pwa_android_box')?.classList.remove('d-none');
    }
});

function installPWA() {
    if (deferredPrompt) {
        deferredPrompt.prompt();
        deferredPrompt.userChoice.then((choiceResult) => {
            if (choiceResult.outcome === 'accepted') {
                dismissPwa();
            }
            deferredPrompt = null;
        });
    }
}

function dismissPwa() {
    const container = document.getElementById('pwa_smart_container');
    if (container) container.classList.add('d-none');
    sessionStorage.setItem('jandalah_pwa_dismissed', '1');
}

function copyPortalUrl() {
    const url = window.location.origin + '/my';
    navigator.clipboard.writeText(url).then(() => {
        const f1 = document.getElementById('copy_feedback_chrome');
        const f2 = document.getElementById('copy_feedback_inapp');
        if (f1) f1.classList.remove('d-none');
        if (f2) f2.classList.remove('d-none');
    });
}

// 4. GPS Geolocation and 1-Tap Toggle
function toggleAttendance() {
    const btn = document.getElementById('btn_toggle_attendance');
    const feedback = document.getElementById('attendance_feedback');
    btn.disabled = true;
    feedback.className = 'mt-2 small fw-bold text-info text-center';
    feedback.innerHTML = ' جاري تحديد الموقع الجغرافي (GPS)...';

    if ("geolocation" in navigator) {
        navigator.geolocation.getCurrentPosition(
            function(pos) {
                sendAttendance(pos.coords.latitude, pos.coords.longitude);
            },
            function(err) {
                console.warn("GPS error: " + err.message);
                sendAttendance(null, null);
            },
            { enableHighAccuracy: true, timeout: 8000, maximumAge: 0 }
        );
    } else {
        sendAttendance(null, null);
    }
}

function sendAttendance(lat, lon) {
    const btn = document.getElementById('btn_toggle_attendance');
    const feedback = document.getElementById('attendance_feedback');
    feedback.innerHTML = ' جاري حفظ تسجيل الحضور في النظام...';

    fetch('/my/attendance/toggle', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({
            params: {
                latitude: lat,
                longitude: lon,
                browser: navigator.userAgent
            }
        })
    })
    .then(res => res.json())
    .then(data => {
        btn.disabled = false;
        if (data.result && data.result.status === 'success') {
            feedback.className = 'mt-2 small fw-bold text-success text-center';
            feedback.innerHTML = ' ' + data.result.message;
            setTimeout(() => { window.location.reload(); }, 1500);
        } else {
            feedback.className = 'mt-2 small fw-bold text-danger text-center';
            feedback.innerHTML = ' ' + (data.result ? data.result.message : 'حدث خطأ في التسجيل');
        }
    })
    .catch(err => {
        btn.disabled = false;
        feedback.className = 'mt-2 small fw-bold text-danger text-center';
        feedback.innerHTML = ' تعذر الاتصال بالسيرفر. يرجى المحاولة ثانية.';
    });
}
